def compute(vars):
    cash_required = vars["v1"]
    remaining_contingent_payments = vars["v2"]
    if remaining_contingent_payments == 0:
        return None
    ratio = cash_required / remaining_contingent_payments
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "cash_required": cash_required,
            "remaining_contingent_payments": remaining_contingent_payments,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
